import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {createChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {ToolRegistry} from '../../orchestration/tools/registry.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';
import {StoreCannotList} from '../../types/sessionStore.js';
import type {SessionStore} from '../../types/sessionStore.js';

describe('list_sessions handling unit test', () => {
  const orchestrator = createChatOrchestrator(
    {} as AIProvider,
    new PromptBuilder({model: 'm'}),
    new ToolRegistry(),
    {sessionStore: {} as SessionStore}
  );

  const mockWs = {
    send: jest.fn(),
    readyState: WebSocket.OPEN,
  } as unknown as WebSocket;

  const mockSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [],
  } as unknown as ChatSession;

  it('answers UNSUPPORTED when history is not enabled in options', async () => {
    const handler = createMessageHandler(orchestrator, {listFor: jest.fn()} as unknown as SessionStore, {});
    await handler(mockWs, mockSession, {type: 'list_sessions'});

    expect(mockWs.send).toHaveBeenCalledWith(expect.stringContaining('UNSUPPORTED'));
  });

  it('answers session_list when history is enabled and store has listFor', async () => {
    const store = {
      listFor: jest.fn().mockResolvedValue([
        {
          sessionId: 's2',
          createdAt: new Date('2026-01-01T00:00:00Z'),
          updatedAt: new Date('2026-01-01T00:00:00Z'),
          entryCount: 0,
        },
      ]),
    } as unknown as SessionStore;
    const handler = createMessageHandler(orchestrator, store, {history: {enabled: true}});
    await handler(mockWs, mockSession, {type: 'list_sessions'});

    expect(mockWs.send).toHaveBeenCalledWith(expect.stringContaining('session_list'));
    expect(mockWs.send).toHaveBeenCalledWith(expect.stringContaining('2026-01-01T00:00:00.000Z'));
  });
});
